"use strict";(self.webpackChunk_iehr_web=self.webpackChunk_iehr_web||[]).push([[6009],{2733:e=>{e.exports=JSON.parse('{"version":{"pluginId":"services","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"servicesSidebar":[{"type":"link","label":"Introduction","href":"/services/","docId":"services","unlisted":false},{"type":"link","label":"Archiva: FHIR-Native Clinical Data Repositories","href":"/services/archiva","docId":"archiva","unlisted":false},{"type":"link","label":"Evolutio: Development FRamework","href":"/services/evolutio","docId":"evolutio","unlisted":false},{"type":"link","label":"Fiscus: Financials & Coverage","href":"/services/fiscus","docId":"fiscus","unlisted":false},{"type":"link","label":"Forma: Questionnaires & Assessments","href":"/services/forma","docId":"forma","unlisted":false},{"type":"link","label":"Maestro: Orchestrating Healthcare AI Automation","href":"/services/maestro","docId":"maestro","unlisted":false},{"type":"link","label":"MAIVE: Multimodal Medical AI for Clinical Reasoning","href":"/services/maive","docId":"maive","unlisted":false},{"type":"link","label":"Mapper: Simplifying Interoperability","href":"/services/mapper","docId":"mapper","unlisted":false},{"type":"link","label":"Medicus: AI-first Practice Management System","href":"/services/medicus","docId":"medicus","unlisted":false},{"type":"link","label":"Nuncius: Secure Communication","href":"/services/nuncius","docId":"nuncius","unlisted":false},{"type":"link","label":"Querium: Analytics for Healthcare","href":"/services/querium","docId":"querium","unlisted":false},{"type":"link","label":"Remedia: Advanced Drug Database","href":"/services/remedia","docId":"remedia","unlisted":false},{"type":"link","label":"Schedula: Scheduling and Appointment Management","href":"/services/schedula","docId":"schedula","unlisted":false},{"type":"link","label":"Scriptus: ePrescription & eDispense","href":"/services/scriptus","docId":"scriptus","unlisted":false},{"type":"link","label":"Securus: OAuth 2.0 Authorization Server","href":"/services/securus","docId":"securus","unlisted":false},{"type":"link","label":"Termini: Terminology Service","href":"/services/termini","docId":"termini","unlisted":false},{"type":"link","label":"Veritas: AI-powered Patient Portal","href":"/services/veritas","docId":"veritas","unlisted":false}]},"docs":{"archiva":{"id":"archiva","title":"Archiva: FHIR-Native Clinical Data Repositories","description":"In the age of digital transformation, healthcare data is being generated at unprecedented scale and complexity. But as clinicians and health systems scramble to manage electronic health records (EHRs), real-time decision-making still hits a wall: fragmented, hard-to-access patient data.","sidebar":"servicesSidebar"},"evolutio":{"id":"evolutio","title":"Evolutio: Development FRamework","description":"The iEHR Evolutio is a comprehensive toolset specifically designed to simplify the development of healthcare applications on the iEHR platform. Although the FHIR\xae standard is powerful, its API can be complex and requires a significant learning curve. The framework empowers developers to overcome these challenges with ease.","sidebar":"servicesSidebar"},"fiscus":{"id":"fiscus","title":"Fiscus: Financials & Coverage","description":"As healthcare evolves toward precision and digital integration, financial data must keep pace. iEHR Fiscus emerges as a forward-thinking solution on the iEHR platform, delivering modular support for FHIR\xae-based financial workflows - from billing and coverage to patient cost estimation and remittance advice.","sidebar":"servicesSidebar"},"forma":{"id":"forma","title":"Forma: Questionnaires & Assessments","description":"Modern healthcare applications demand smart, interoperable tools to capture patient data efficiently. iEHR Forma is a module on the iEHR platform designed to build, deploy, and manage FHIR\xae-based Questionnaires and Assessments with ease. Whether you\'re digitizing intake forms, behavioral health screenings, or clinical assessments, iEHR Forma brings speed, compliance, and scalability to the table.","sidebar":"servicesSidebar"},"maestro":{"id":"maestro","title":"Maestro: Orchestrating Healthcare AI Automation","description":"Healthcare demands efficiency, accuracy, and security - but manual processes and outdated systems slow down innovation. iEHR Maestro empowers healthcare organizations by automating AI workflows, streamlining operations, and enhancing patient care with data-driven precision.","sidebar":"servicesSidebar"},"maive":{"id":"maive","title":"MAIVE: Multimodal Medical AI for Clinical Reasoning","description":"MAIVE is a next\u2011generation medical AI platform built from the ground up to deliver scalable multimodal intelligence, long\u2011context reasoning, and seamless interoperability with real\u2011world clinical systems. Designed for developers, researchers, and healthcare innovators, MAIVE brings together high\u2011performance machine learning with a privacy\u2011preserving architecture that runs efficiently on consumer\u2011grade hardware.","sidebar":"servicesSidebar"},"mapper":{"id":"mapper","title":"Mapper: Simplifying Interoperability","description":"Overview","sidebar":"servicesSidebar"},"medicus":{"id":"medicus","title":"Medicus: AI-first Practice Management System","description":"Modern medical practice is about more than diagnosis and treatment - it\u2019s about managing time, data, compliance, and patient satisfaction. This is where an AI-first Practice Management System (AI-PMS) steps in as a digital backbone of any healthcare operation.","sidebar":"servicesSidebar"},"nuncius":{"id":"nuncius","title":"Nuncius: Secure Communication","description":"In the ever-evolving landscape of digital health, Nuncius is making waves with its groundbreaking approach to secure communication in clinical settings. A FHIR-native, AI-enabled communication system designed to bridge gaps between healthcare providers, streamline workflows, and safeguard sensitive patient data.","sidebar":"servicesSidebar"},"querium":{"id":"querium","title":"Querium: Analytics for Healthcare","description":"In the fast-moving world of digital health, where interoperability, security, and usability are top priorities, healthcare developers need tools that are just as specialized as the data they work with. Meet Querium  -  the first Querium-based IDE designed from the ground up for FHIR, SMART on FHIR, and other healthcare-grade APIs.","sidebar":"servicesSidebar"},"remedia":{"id":"remedia","title":"Remedia: Advanced Drug Database","description":"Overview","sidebar":"servicesSidebar"},"schedula":{"id":"schedula","title":"Schedula: Scheduling and Appointment Management","description":"As healthcare ecosystems evolve toward digitization and interoperability, the implementation of a FHIR-based scheduling and appointment management system represents a significant step forward. Designed for hospitals, clinics, doctors, and patients, this system leverages HL7\u2019s FHIR standard to ensure reliable, standardized, and secure data exchange between disparate systems.","sidebar":"servicesSidebar"},"scriptus":{"id":"scriptus","title":"Scriptus: ePrescription & eDispense","description":"In an increasingly interconnected world, seamless and secure access to healthcare data is vital - not only for improving patient outcomes, but also for realizing the full promise of digital medicine. At the heart of iEHR Scriptus\u2019s digital services for daily healthcare delivery lie two pivotal tools: ePrescription and eDispense.","sidebar":"servicesSidebar"},"securus":{"id":"securus","title":"Securus: OAuth 2.0 Authorization Server","description":"In a world where electronic health records, diagnostic imaging, and patient portals are increasingly digitized, security, privacy, and interoperability are no longer just compliance concerns - they\'re mission-critical. Enter Securus, a modern OAuth 2.0 authorization server designed with native FAPI 2.0 Security Profile compliance to safeguard Protected Health Information (PHI) across healthcare APIs.","sidebar":"servicesSidebar"},"services":{"id":"services","title":"Introduction","description":"The iEHR platform offers a unified ecosystem of smart, interoperable, and AI-powered services built on HL7\u2019s FHIR standard. From data repositories to intelligent scheduling, iEHR transforms the way hospitals, clinics, developers, and patients engage with digital healthcare.","sidebar":"servicesSidebar"},"termini":{"id":"termini","title":"Termini: Terminology Service","description":"iEHR.ai Terminology Service enable healthcare applications to seamlessly interact with standardized medical terminologies. By eliminating the need for deep expertise in code systems, value sets, and concept maps, this service streamlines data interoperability. Expanding FHIR Terminology Services requires integrating advanced operations, improving system performance, and enhancing support for diverse healthcare standards.","sidebar":"servicesSidebar"},"veritas":{"id":"veritas","title":"Veritas: AI-powered Patient Portal","description":"iEHR Veritas leverages the HL7 FHIR standard to provide patients with secure, real-time access to their health data. Unlike traditional portals tied to proprietary EHR systems, FHIR-based portals are interoperable, modular, and API-driven, enabling seamless integration across healthcare ecosystems.","sidebar":"servicesSidebar"}}}}')}}]);